@startuml

class Bettor {
  + name : string
}

class Race {
  + id : string
}

class Runner {
  + name : string
}

class Horse {
}

class Jockey {
  + name : string
}

class Bet {
  + amount : float
  + odds : float
}

Horse "1" *-- "1" Runner
Jockey "1" -- "1" Runner

Race "1" *-- "1..*" Runner
Race "1" o-- "1" Runner : winner

Bettor "1" -- "*" Bet
Bet "*" -- "1" Race
Bet "*" -- "1" Runner

@enduml

